uint64_t gaussian_uint64_generator(PCG* generator, const uint64_t mean, const uint64_t standard_deviation) {
    const double UNIFORM_FLOOR = 0.00000000000000011102230246251565404;
    const double TWO_PI = 6.28318530717958647692;
    const double SQUARE_ROOT_EXPONENT = 0.5;
    const double TWO_64_REAL = 18446744073709551616.0;

    double uniform_first = uniform_double_generator(generator, UNIFORM_FLOOR, 1.0);
    double uniform_second = uniform_double_generator(generator, 0.0, 1.0);
    double radius_squared = (-2.0) * natural_logarithm_double(uniform_first);
    double radius = power_double(radius_squared, SQUARE_ROOT_EXPONENT);
    double standard_normal = radius * cosine_double(TWO_PI * uniform_second);
    double scaled = ((double)standard_deviation) * standard_normal;
    double magnitude_real = round_double(absolute_value_double(scaled));
    uint64_t magnitude = UINT64_MAX;
    if(magnitude_real < TWO_64_REAL) {
        magnitude = (uint64_t)magnitude_real;
    }
    uint64_t output = 0;
    if(scaled < 0.0) {
        if(magnitude > mean) {
            output = 0;
        }
        else {
            output = mean - magnitude;
        }
    }
    else {
        if(magnitude > (UINT64_MAX - mean)) {
            output = UINT64_MAX;
        }
        else {
            output = mean + magnitude;
        }
    }
    return output;
}

