Tensor categorical_cross_entropy(const Tensor prediction_input, const Tensor target_input, const uint8_t reduction_type) {
    const size_t BATCH_DIMENSION = 0;

    size_t class_dimension = prediction_input.total_dimensions - 1;
    size_t batch_size = prediction_input.dimensions[BATCH_DIMENSION];
    size_t total_classes = prediction_input.dimensions[class_dimension];

    size_t batch_stride = 1;
    for(size_t i = (BATCH_DIMENSION + 1); i < prediction_input.total_dimensions; i++) {
        batch_stride *= prediction_input.dimensions[i];
    }

    size_t* output_dimensions = malloc(prediction_input.total_dimensions * sizeof(size_t));
    for(size_t i = 0; i < prediction_input.total_dimensions; i++) {
        output_dimensions[i] = 1;
    }
    if(reduction_type == 0) {
        output_dimensions[BATCH_DIMENSION] = batch_size;
    }
    Tensor output = create_tensor(prediction_input.total_dimensions, output_dimensions);
    free(output_dimensions);
    set_tensor_data_to_zeros(&output);

    float total_losses = 0.0f;
    for(size_t batch = 0; batch < batch_size; batch++) {
        size_t batch_offset = batch * batch_stride;

        float sample_loss = 0.0f;
        for(size_t vector = 0; vector < batch_stride; vector += total_classes) {
            size_t vector_offset = batch_offset + vector;

            float maximum_value = prediction_input.data[vector_offset];
            for(size_t i = 1; i < total_classes; i++) {
                if(prediction_input.data[vector_offset + i] > maximum_value) { maximum_value = prediction_input.data[vector_offset + i]; }
            }

            float exponential_sum = 0.0f;
            for(size_t i = 0; i < total_classes; i++) {
                exponential_sum += exponential_float(prediction_input.data[vector_offset + i] - maximum_value);
            }
            float exponential_sum_logarithm = natural_logarithm_float(exponential_sum);

            for(size_t i = 0; i < total_classes; i++) {
                float probability_logarithm = (prediction_input.data[vector_offset + i] - maximum_value) - exponential_sum_logarithm;
                sample_loss += (-1.0f * target_input.data[vector_offset + i]) * probability_logarithm;
            }
        }

        if(reduction_type == 0) {
            output.data[batch] = sample_loss;
        }
        else {
            total_losses += sample_loss;
        }
    }
    if(reduction_type == 1) {
        output.data[0] = total_losses;
    }
    else if(reduction_type == 2) {
        output.data[0] = total_losses / (float)batch_size;
    }
    return output;
}

Tensor mean_square_error(const Tensor prediction_input, const Tensor target_input, const uint8_t reduction_type) {
    const size_t BATCH_DIMENSION = 0;

    size_t batch_size = prediction_input.dimensions[BATCH_DIMENSION];

    size_t batch_stride = 1;
    for(size_t i = (BATCH_DIMENSION + 1); i < prediction_input.total_dimensions; i++) {
        batch_stride *= prediction_input.dimensions[i];
    }

    size_t* output_dimensions = malloc(prediction_input.total_dimensions * sizeof(size_t));
    for(size_t i = 0; i < prediction_input.total_dimensions; i++) {
        output_dimensions[i] = 1;
    }
    if(reduction_type == 0) {
        output_dimensions[BATCH_DIMENSION] = batch_size;
    }
    Tensor output = create_tensor(prediction_input.total_dimensions, output_dimensions);
    free(output_dimensions);
    set_tensor_data_to_zeros(&output);

    float total_losses = 0.0f;
    for(size_t batch = 0; batch < batch_size; batch++) {
        size_t batch_offset = batch * batch_stride;

        float sample_loss = 0.0f;
        for(size_t i = 0; i < batch_stride; i++) {
            float difference = prediction_input.data[batch_offset + i] - target_input.data[batch_offset + i];
            sample_loss += difference * difference;
        }
        sample_loss /= (float)batch_stride;

        if(reduction_type == 0) {
            output.data[batch] = sample_loss;
        }
        else {
            total_losses += sample_loss;
        }
    }
    if(reduction_type == 1) {
        output.data[0] = total_losses;
    }
    else if(reduction_type == 2) {
        output.data[0] = total_losses / (float)batch_size;
    }
    return output;
}

Tensor kl_divergence(const Tensor prediction_input, const Tensor target_input, const uint8_t reduction_type) {
    const size_t BATCH_DIMENSION = 0;

    size_t class_dimension = prediction_input.total_dimensions - 1;
    size_t batch_size = prediction_input.dimensions[BATCH_DIMENSION];
    size_t total_classes = prediction_input.dimensions[class_dimension];

    size_t batch_stride = 1;
    for(size_t i = (BATCH_DIMENSION + 1); i < prediction_input.total_dimensions; i++) {
        batch_stride *= prediction_input.dimensions[i];
    }

    size_t* output_dimensions = malloc(prediction_input.total_dimensions * sizeof(size_t));
    for(size_t i = 0; i < prediction_input.total_dimensions; i++) {
        output_dimensions[i] = 1;
    }
    if(reduction_type == 0) {
        output_dimensions[BATCH_DIMENSION] = batch_size;
    }
    Tensor output = create_tensor(prediction_input.total_dimensions, output_dimensions);
    free(output_dimensions);
    set_tensor_data_to_zeros(&output);

    float total_losses = 0.0f;
    for(size_t batch = 0; batch < batch_size; batch++) {
        size_t batch_offset = batch * batch_stride;

        float sample_loss = 0.0f;
        for(size_t vector = 0; vector < batch_stride; vector += total_classes) {
            size_t vector_offset = batch_offset + vector;

            float maximum_value = prediction_input.data[vector_offset];
            for(size_t i = 1; i < total_classes; i++) {
                if(prediction_input.data[vector_offset + i] > maximum_value) { maximum_value = prediction_input.data[vector_offset + i]; }
            }

            float exponential_sum = 0.0f;
            for(size_t i = 0; i < total_classes; i++) {
                exponential_sum += exponential_float(prediction_input.data[vector_offset + i] - maximum_value);
            }
            float exponential_sum_logarithm = natural_logarithm_float(exponential_sum);

            for(size_t i = 0; i < total_classes; i++) {
                float target_value = target_input.data[vector_offset + i];
                if(target_value > 0.0f) {
                    float probability_logarithm = (prediction_input.data[vector_offset + i] - maximum_value) - exponential_sum_logarithm;
                    sample_loss += target_value * (natural_logarithm_float(target_value) - probability_logarithm);
                }
            }
        }

        if(reduction_type == 0) {
            output.data[batch] = sample_loss;
        }
        else {
            total_losses += sample_loss;
        }
    }
    if(reduction_type == 1) {
        output.data[0] = total_losses;
    }
    else if(reduction_type == 2) {
        output.data[0] = total_losses / (float)batch_size;
    }
    return output;
}

Tensor huber_loss(const Tensor prediction_input, const Tensor target_input, const uint8_t reduction_type, const float delta) {
    const size_t BATCH_DIMENSION = 0;

    size_t batch_size = prediction_input.dimensions[BATCH_DIMENSION];

    size_t batch_stride = 1;
    for(size_t i = (BATCH_DIMENSION + 1); i < prediction_input.total_dimensions; i++) {
        batch_stride *= prediction_input.dimensions[i];
    }

    size_t* output_dimensions = malloc(prediction_input.total_dimensions * sizeof(size_t));
    for(size_t i = 0; i < prediction_input.total_dimensions; i++) {
        output_dimensions[i] = 1;
    }
    if(reduction_type == 0) {
        output_dimensions[BATCH_DIMENSION] = batch_size;
    }
    Tensor output = create_tensor(prediction_input.total_dimensions, output_dimensions);
    free(output_dimensions);
    set_tensor_data_to_zeros(&output);

    float total_losses = 0.0f;
    for(size_t batch = 0; batch < batch_size; batch++) {
        size_t batch_offset = batch * batch_stride;

        float sample_loss = 0.0f;
        for(size_t i = 0; i < batch_stride; i++) {
            float difference = prediction_input.data[batch_offset + i] - target_input.data[batch_offset + i];
            float absolute_difference = absolute_value_float(difference);
            if(absolute_difference <= delta) {
                sample_loss += (0.5f * difference) * difference;
            }
            else {
                sample_loss += delta * (absolute_difference - (0.5f * delta));
            }
        }
        sample_loss /= (float)batch_stride;

        if(reduction_type == 0) {
            output.data[batch] = sample_loss;
        }
        else {
            total_losses += sample_loss;
        }
    }
    if(reduction_type == 1) {
        output.data[0] = total_losses;
    }
    else if(reduction_type == 2) {
        output.data[0] = total_losses / (float)batch_size;
    }
    return output;
}

Tensor dropout(const Tensor input, const float drop_probability, const uint64_t seed, const uint64_t total_training_steps, const uint64_t current_time_step) {
    const uint64_t MULTIPLIER = UINT64_C(6364136223846793005);
    const uint64_t INCREMENT = UINT64_C(1442695040888963407);
    const uint64_t TRAINING_STEP_MULTIPLIER = UINT64_C(11400714819323198485);
    const uint64_t TIME_STEP_MULTIPLIER = UINT64_C(9223372036854775837);
    const uint64_t TWO_32 = UINT64_C(4294967296);
    const uint64_t TWO_40 = UINT64_C(1099511627776);
    const float TWO_24_REAL = 16777216.0f;

    Tensor output = create_tensor(input.total_dimensions, input.dimensions);

    size_t total_elements = 1;
    for(size_t i = 0; i < input.total_dimensions; i++) {
        total_elements *= input.dimensions[i];
    }

    float keep_probability = 1.0f - drop_probability;
    float scale = (keep_probability > 0.0f) ? (1.0f / keep_probability) : 0.0f;

    uint64_t key = (seed + (total_training_steps * TRAINING_STEP_MULTIPLIER)) + (current_time_step * TIME_STEP_MULTIPLIER);
    key = (key * MULTIPLIER) + INCREMENT;
    key = (key * MULTIPLIER) + INCREMENT;
    key = (key - (key % 2)) + 1;

    for(size_t i = 0; i < total_elements; i++) {
        uint64_t counter_product = ((uint64_t)i) * key;
        uint64_t offset_product = counter_product + key;
        uint64_t mixed = counter_product;
        mixed = (mixed * mixed) + counter_product;
        mixed = ((mixed % TWO_32) * TWO_32) + (mixed / TWO_32);
        mixed = (mixed * mixed) + offset_product;
        mixed = ((mixed % TWO_32) * TWO_32) + (mixed / TWO_32);
        mixed = (mixed * mixed) + counter_product;
        mixed = ((mixed % TWO_32) * TWO_32) + (mixed / TWO_32);
        mixed = (mixed * mixed) + offset_product;

        uint64_t mantissa_bits = mixed / TWO_40;
        float uniform_sample = ((float)mantissa_bits) / TWO_24_REAL;
        if(uniform_sample < drop_probability) {
            output.data[i] = 0.0f;
        }
        else {
            output.data[i] = input.data[i] * scale;
        }
    }
    return output;
}

Tensor droppath(const Tensor input, const size_t sample_dimension, const float drop_probability, const uint64_t seed, const uint64_t total_training_steps, const uint64_t current_time_step) {
    const uint64_t MULTIPLIER = UINT64_C(6364136223846793005);
    const uint64_t INCREMENT = UINT64_C(1442695040888963407);
    const uint64_t TRAINING_STEP_MULTIPLIER = UINT64_C(11400714819323198485);
    const uint64_t TIME_STEP_MULTIPLIER = UINT64_C(9223372036854775837);
    const uint64_t TWO_32 = UINT64_C(4294967296);
    const uint64_t TWO_40 = UINT64_C(1099511627776);
    const float TWO_24_REAL = 16777216.0f;

    Tensor output = create_tensor(input.total_dimensions, input.dimensions);

    size_t total_samples = 1;
    size_t sample_size = 1;
    for(size_t i = 0; i < input.total_dimensions; i++) {
        if(i < sample_dimension) { total_samples *= input.dimensions[i]; }
        else { sample_size *= input.dimensions[i]; }
    }

    float keep_probability = 1.0f - drop_probability;
    float scale = (keep_probability > 0.0f) ? (1.0f / keep_probability) : 0.0f;

    uint64_t key = (seed + (total_training_steps * TRAINING_STEP_MULTIPLIER)) + (current_time_step * TIME_STEP_MULTIPLIER);
    key = (key * MULTIPLIER) + INCREMENT;
    key = (key * MULTIPLIER) + INCREMENT;
    key = (key - (key % 2)) + 1;

    for(size_t sample = 0; sample < total_samples; sample++) {
        size_t sample_offset = sample * sample_size;

        uint64_t counter_product = ((uint64_t)sample) * key;
        uint64_t offset_product = counter_product + key;
        uint64_t mixed = counter_product;
        mixed = (mixed * mixed) + counter_product;
        mixed = ((mixed % TWO_32) * TWO_32) + (mixed / TWO_32);
        mixed = (mixed * mixed) + offset_product;
        mixed = ((mixed % TWO_32) * TWO_32) + (mixed / TWO_32);
        mixed = (mixed * mixed) + counter_product;
        mixed = ((mixed % TWO_32) * TWO_32) + (mixed / TWO_32);
        mixed = (mixed * mixed) + offset_product;

        uint64_t mantissa_bits = mixed / TWO_40;
        float uniform_sample = ((float)mantissa_bits) / TWO_24_REAL;
        if(uniform_sample < drop_probability) {
            for(size_t i = 0; i < sample_size; i++) {
                output.data[sample_offset + i] = 0.0f;
            }
        }
        else {
            for(size_t i = 0; i < sample_size; i++) {
                output.data[sample_offset + i] = input.data[sample_offset + i] * scale;
            }
        }
    }
    return output;
}

Tensor zoneout(const Tensor current_input, const Tensor previous_input, const float zoneout_probability, const uint64_t seed, const uint64_t total_training_steps, const uint64_t current_time_step) {
    const uint64_t MULTIPLIER = UINT64_C(6364136223846793005);
    const uint64_t INCREMENT = UINT64_C(1442695040888963407);
    const uint64_t TRAINING_STEP_MULTIPLIER = UINT64_C(11400714819323198485);
    const uint64_t TIME_STEP_MULTIPLIER = UINT64_C(9223372036854775837);
    const uint64_t TWO_32 = UINT64_C(4294967296);
    const uint64_t TWO_40 = UINT64_C(1099511627776);
    const float TWO_24_REAL = 16777216.0f;

    Tensor output = create_tensor(current_input.total_dimensions, current_input.dimensions);

    size_t total_elements = 1;
    for(size_t i = 0; i < current_input.total_dimensions; i++) {
        total_elements *= current_input.dimensions[i];
    }

    uint64_t key = (seed + (total_training_steps * TRAINING_STEP_MULTIPLIER)) + (current_time_step * TIME_STEP_MULTIPLIER);
    key = (key * MULTIPLIER) + INCREMENT;
    key = (key * MULTIPLIER) + INCREMENT;
    key = (key - (key % 2)) + 1;

    for(size_t i = 0; i < total_elements; i++) {
        uint64_t counter_product = ((uint64_t)i) * key;
        uint64_t offset_product = counter_product + key;
        uint64_t mixed = counter_product;
        mixed = (mixed * mixed) + counter_product;
        mixed = ((mixed % TWO_32) * TWO_32) + (mixed / TWO_32);
        mixed = (mixed * mixed) + offset_product;
        mixed = ((mixed % TWO_32) * TWO_32) + (mixed / TWO_32);
        mixed = (mixed * mixed) + counter_product;
        mixed = ((mixed % TWO_32) * TWO_32) + (mixed / TWO_32);
        mixed = (mixed * mixed) + offset_product;

        uint64_t mantissa_bits = mixed / TWO_40;
        float uniform_sample = ((float)mantissa_bits) / TWO_24_REAL;
        if(uniform_sample < zoneout_probability) {
            output.data[i] = previous_input.data[i];
        }
        else {
            output.data[i] = current_input.data[i];
        }
    }
    return output;
}

void resize_tensor_gradients(const Tensor input, const Tensor upstream_gradients, Tensor* input_gradients) {
    size_t total_elements = 1;
    for(size_t i = 0; i < upstream_gradients.total_dimensions; i++) {
        total_elements *= upstream_gradients.dimensions[i];
    }

    for(size_t element_index = 0; element_index < total_elements; element_index++) {
        size_t remainder = element_index;
        size_t input_index = 0;
        size_t input_stride = 1;
        uint8_t is_in_bounds = 1;
        for(size_t dimension = input.total_dimensions; dimension > 0; dimension--) {
            size_t coordinate = remainder % upstream_gradients.dimensions[dimension - 1];
            remainder /= upstream_gradients.dimensions[dimension - 1];
            if(coordinate >= input.dimensions[dimension - 1]) {
                is_in_bounds = 0;
                break;
            }
            input_index += coordinate * input_stride;
            input_stride *= input.dimensions[dimension - 1];
        }
        if(is_in_bounds == 1) {
            input_gradients->data[input_index] += upstream_gradients.data[element_index];
        }
    }
}

void concatenate_tensors_gradients(const Tensor input1, const Tensor input2, const Tensor upstream_gradients, Tensor* input1_gradients, Tensor* input2_gradients, const size_t concatenation_dimension) {
    size_t total_blocks = 1;
    size_t block_size = 1;
    for(size_t i = 0; i < upstream_gradients.total_dimensions; i++) {
        if(i < concatenation_dimension) {
            total_blocks *= input1.dimensions[i];
        }
        if(i > concatenation_dimension) {
            block_size *= input1.dimensions[i];
        }
    }

    size_t input1_block_size = input1.dimensions[concatenation_dimension] * block_size;
    size_t input2_block_size = input2.dimensions[concatenation_dimension] * block_size;
    size_t output_block_size = upstream_gradients.dimensions[concatenation_dimension] * block_size;
    for(size_t block_index = 0; block_index < total_blocks; block_index++) {
        size_t output_offset = block_index * output_block_size;
        for(size_t i = 0; i < input1_block_size; i++) {
            input1_gradients->data[(block_index * input1_block_size) + i] += upstream_gradients.data[output_offset + i];
        }
        for(size_t i = 0; i < input2_block_size; i++) {
            input2_gradients->data[(block_index * input2_block_size) + i] += upstream_gradients.data[output_offset + input1_block_size + i];
        }
    }
}

void tensor_addition_gradients(const Tensor input1, const Tensor input2, const Tensor upstream_gradients, Tensor* input1_gradients, Tensor* input2_gradients) {
    size_t total_dimensions = upstream_gradients.total_dimensions;
    size_t* input1_strides = malloc(total_dimensions * sizeof(size_t));
    size_t* input2_strides = malloc(total_dimensions * sizeof(size_t));
    size_t* output_coordinates = malloc(total_dimensions * sizeof(size_t));
    size_t input1_stride = 1;
    size_t input2_stride = 1;
    for(size_t dimension = total_dimensions; dimension > 0; dimension--) {
        input1_strides[dimension - 1] = input1_stride;
        input2_strides[dimension - 1] = input2_stride;
        if(input1.dimensions[dimension - 1] == 1) {
            input1_strides[dimension - 1] = 0;
        }
        if(input2.dimensions[dimension - 1] == 1) {
            input2_strides[dimension - 1] = 0;
        }
        input1_stride *= input1.dimensions[dimension - 1];
        input2_stride *= input2.dimensions[dimension - 1];
        output_coordinates[dimension - 1] = 0;
    }

    size_t total_elements = 1;
    for(size_t i = 0; i < total_dimensions; i++) {
        total_elements *= upstream_gradients.dimensions[i];
    }

    size_t input1_index = 0;
    size_t input2_index = 0;
    for(size_t output_index = 0; output_index < total_elements; output_index++) {
        input1_gradients->data[input1_index] += upstream_gradients.data[output_index];
        input2_gradients->data[input2_index] += upstream_gradients.data[output_index];

        for(size_t dimension = total_dimensions; dimension > 0; dimension--) {
            output_coordinates[dimension - 1]++;
            input1_index += input1_strides[dimension - 1];
            input2_index += input2_strides[dimension - 1];
            if(output_coordinates[dimension - 1] < upstream_gradients.dimensions[dimension - 1]) {
                break;
            }
            input1_index -= input1_strides[dimension - 1] * upstream_gradients.dimensions[dimension - 1];
            input2_index -= input2_strides[dimension - 1] * upstream_gradients.dimensions[dimension - 1];
            output_coordinates[dimension - 1] = 0;
        }
    }

    free(input1_strides);
    free(input2_strides);
    free(output_coordinates);
}

void tensor_multiply_gradients(const Tensor input1, const Tensor input2, const Tensor upstream_gradients, Tensor* input1_gradients, Tensor* input2_gradients) {
    size_t total_dimensions = upstream_gradients.total_dimensions;
    size_t* input1_strides = malloc(total_dimensions * sizeof(size_t));
    size_t* input2_strides = malloc(total_dimensions * sizeof(size_t));
    size_t* output_coordinates = malloc(total_dimensions * sizeof(size_t));
    size_t input1_stride = 1;
    size_t input2_stride = 1;
    for(size_t dimension = total_dimensions; dimension > 0; dimension--) {
        input1_strides[dimension - 1] = input1_stride;
        input2_strides[dimension - 1] = input2_stride;
        if(input1.dimensions[dimension - 1] == 1) {
            input1_strides[dimension - 1] = 0;
        }
        if(input2.dimensions[dimension - 1] == 1) {
            input2_strides[dimension - 1] = 0;
        }
        input1_stride *= input1.dimensions[dimension - 1];
        input2_stride *= input2.dimensions[dimension - 1];
        output_coordinates[dimension - 1] = 0;
    }

    size_t total_elements = 1;
    for(size_t i = 0; i < total_dimensions; i++) {
        total_elements *= upstream_gradients.dimensions[i];
    }

    size_t input1_index = 0;
    size_t input2_index = 0;
    for(size_t output_index = 0; output_index < total_elements; output_index++) {
        float upstream_gradient = upstream_gradients.data[output_index];
        input1_gradients->data[input1_index] += upstream_gradient * input2.data[input2_index];
        input2_gradients->data[input2_index] += upstream_gradient * input1.data[input1_index];

        for(size_t dimension = total_dimensions; dimension > 0; dimension--) {
            output_coordinates[dimension - 1]++;
            input1_index += input1_strides[dimension - 1];
            input2_index += input2_strides[dimension - 1];
            if(output_coordinates[dimension - 1] < upstream_gradients.dimensions[dimension - 1]) {
                break;
            }
            input1_index -= input1_strides[dimension - 1] * upstream_gradients.dimensions[dimension - 1];
            input2_index -= input2_strides[dimension - 1] * upstream_gradients.dimensions[dimension - 1];
            output_coordinates[dimension - 1] = 0;
        }
    }

    free(input1_strides);
    free(input2_strides);
    free(output_coordinates);
}

void tensor_matmul_gradients(const Tensor input1, const Tensor input2, const Tensor upstream_gradients, Tensor* input1_gradients, Tensor* input2_gradients) {
    size_t total_batch_dimensions = input1.total_dimensions - 2;
    size_t rows = input1.dimensions[total_batch_dimensions];
    size_t inner_size = input1.dimensions[total_batch_dimensions + 1];
    size_t columns = input2.dimensions[total_batch_dimensions + 1];

    size_t* input1_strides = malloc(total_batch_dimensions * sizeof(size_t));
    size_t* input2_strides = malloc(total_batch_dimensions * sizeof(size_t));
    size_t* batch_coordinates = malloc(total_batch_dimensions * sizeof(size_t));
    size_t input1_stride = rows * inner_size;
    size_t input2_stride = inner_size * columns;
    for(size_t dimension = total_batch_dimensions; dimension > 0; dimension--) {
        input1_strides[dimension - 1] = input1_stride;
        input2_strides[dimension - 1] = input2_stride;
        if(input1.dimensions[dimension - 1] == 1) {
            input1_strides[dimension - 1] = 0;
        }
        if(input2.dimensions[dimension - 1] == 1) {
            input2_strides[dimension - 1] = 0;
        }
        input1_stride *= input1.dimensions[dimension - 1];
        input2_stride *= input2.dimensions[dimension - 1];
        batch_coordinates[dimension - 1] = 0;
    }

    size_t total_batches = 1;
    for(size_t i = 0; i < total_batch_dimensions; i++) {
        total_batches *= upstream_gradients.dimensions[i];
    }

    size_t input1_offset = 0;
    size_t input2_offset = 0;
    size_t output_offset = 0;
    for(size_t batch_index = 0; batch_index < total_batches; batch_index++) {
        for(size_t row = 0; row < rows; row++) {
            size_t output_row_offset = output_offset + (row * columns);
            for(size_t inner_index = 0; inner_index < inner_size; inner_index++) {
                size_t left_index = input1_offset + (row * inner_size) + inner_index;
                size_t right_row_offset = input2_offset + (inner_index * columns);
                float left_value = input1.data[left_index];
                float left_gradient = 0.0f;
                for(size_t column = 0; column < columns; column++) {
                    float upstream_gradient = upstream_gradients.data[output_row_offset + column];
                    left_gradient += upstream_gradient * input2.data[right_row_offset + column];
                    input2_gradients->data[right_row_offset + column] += left_value * upstream_gradient;
                }
                input1_gradients->data[left_index] += left_gradient;
            }
        }
        output_offset += rows * columns;

        for(size_t dimension = total_batch_dimensions; dimension > 0; dimension--) {
            batch_coordinates[dimension - 1]++;
            input1_offset += input1_strides[dimension - 1];
            input2_offset += input2_strides[dimension - 1];
            if(batch_coordinates[dimension - 1] < upstream_gradients.dimensions[dimension - 1]) {
                break;
            }
            input1_offset -= input1_strides[dimension - 1] * upstream_gradients.dimensions[dimension - 1];
            input2_offset -= input2_strides[dimension - 1] * upstream_gradients.dimensions[dimension - 1];
            batch_coordinates[dimension - 1] = 0;
        }
    }

    free(input1_strides);
    free(input2_strides);
    free(batch_coordinates);
}

void tensor_convolution_gradients(const Tensor input, const Tensor kernels, const Tensor upstream_gradients, Tensor* input_gradients, Tensor* kernel_gradients, const size_t total_kernels, const size_t kernel_dimension, const size_t padding) {
    size_t total_batch_dimensions = 0;
    size_t channels = 1;
    if(input.total_dimensions >= 3) {
        total_batch_dimensions = input.total_dimensions - 3;
        channels = input.dimensions[total_batch_dimensions];
    }
    size_t input_height = input.dimensions[input.total_dimensions - 2];
    size_t input_width = input.dimensions[input.total_dimensions - 1];
    size_t output_height = (input_height + (2 * padding) + 1) - kernel_dimension;
    size_t output_width = (input_width + (2 * padding) + 1) - kernel_dimension;

    size_t total_batches = 1;
    for(size_t i = 0; i < total_batch_dimensions; i++) {
        total_batches *= input.dimensions[i];
    }

    size_t input_channel_size = input_height * input_width;
    size_t input_size = channels * input_channel_size;
    size_t kernel_channel_size = kernel_dimension * kernel_dimension;
    size_t kernel_size = channels * kernel_channel_size;
    size_t output_plane_size = output_height * output_width;

    size_t input_offset = 0;
    size_t output_offset = 0;
    for(size_t batch_index = 0; batch_index < total_batches; batch_index++) {
        for(size_t kernel_index = 0; kernel_index < total_kernels; kernel_index++) {
            for(size_t channel = 0; channel < channels; channel++) {
                size_t input_channel_offset = input_offset + (channel * input_channel_size);
                size_t kernel_channel_offset = (kernel_index * kernel_size) + (channel * kernel_channel_size);

                for(size_t kernel_row = 0; kernel_row < kernel_dimension; kernel_row++) {
                    size_t first_output_row = 0;
                    size_t last_output_row = 0;
                    if(kernel_row < padding) {
                        first_output_row = padding - kernel_row;
                    }
                    if(kernel_row < (input_height + padding)) {
                        last_output_row = (input_height + padding) - kernel_row;
                    }
                    if(last_output_row > output_height) {
                        last_output_row = output_height;
                    }

                    for(size_t kernel_column = 0; kernel_column < kernel_dimension; kernel_column++) {
                        size_t first_output_column = 0;
                        size_t last_output_column = 0;
                        if(kernel_column < padding) {
                            first_output_column = padding - kernel_column;
                        }
                        if(kernel_column < (input_width + padding)) {
                            last_output_column = (input_width + padding) - kernel_column;
                        }
                        if(last_output_column > output_width) {
                            last_output_column = output_width;
                        }

                        size_t weight_index = kernel_channel_offset + (kernel_row * kernel_dimension) + kernel_column;
                        float weight = kernels.data[weight_index];
                        float weight_gradient = 0.0f;
                        for(size_t output_row = first_output_row; output_row < last_output_row; output_row++) {
                            size_t input_row_offset = input_channel_offset + (((output_row + kernel_row) - padding) * input_width);
                            size_t output_row_offset = output_offset + (output_row * output_width);
                            for(size_t output_column = first_output_column; output_column < last_output_column; output_column++) {
                                size_t input_index = input_row_offset + ((output_column + kernel_column) - padding);
                                float upstream_gradient = upstream_gradients.data[output_row_offset + output_column];
                                input_gradients->data[input_index] += weight * upstream_gradient;
                                weight_gradient += upstream_gradient * input.data[input_index];
                            }
                        }
                        kernel_gradients->data[weight_index] += weight_gradient;
                    }
                }
            }
            output_offset += output_plane_size;
        }
        input_offset += input_size;
    }
}

void tensor_layer_normalization_gradients(const Tensor input, const Tensor gamma, const Tensor beta, const Tensor upstream_gradients, Tensor* input_gradients, Tensor* gamma_gradients, Tensor* beta_gradients, const size_t normalization_dimension, const float epsilon) {
    (void)beta;
    const float SQUARE_ROOT_EXPONENT = 0.5f;

    size_t total_blocks = 1;
    size_t block_size = 1;
    for(size_t i = 0; i < input.total_dimensions; i++) {
        if(i < normalization_dimension) {
            total_blocks *= input.dimensions[i];
        }
        if(i > normalization_dimension) {
            block_size *= input.dimensions[i];
        }
    }
    size_t normalization_size = input.dimensions[normalization_dimension];
    size_t outer_block_size = normalization_size * block_size;
    float normalization_count = (float)normalization_size;

    float* means = malloc(block_size * sizeof(float));
    float* inverse_standard_deviations = malloc(block_size * sizeof(float));
    float* gradient_means = malloc(block_size * sizeof(float));
    float* gradient_projection_means = malloc(block_size * sizeof(float));

    for(size_t block_index = 0; block_index < total_blocks; block_index++) {
        size_t block_offset = block_index * outer_block_size;
        for(size_t position = 0; position < block_size; position++) {
            means[position] = 0.0f;
            inverse_standard_deviations[position] = 0.0f;
            gradient_means[position] = 0.0f;
            gradient_projection_means[position] = 0.0f;
        }

        for(size_t normalization_index = 0; normalization_index < normalization_size; normalization_index++) {
            size_t row_offset = block_offset + (normalization_index * block_size);
            for(size_t position = 0; position < block_size; position++) {
                means[position] += input.data[row_offset + position];
            }
        }
        for(size_t position = 0; position < block_size; position++) {
            means[position] /= normalization_count;
        }

        for(size_t normalization_index = 0; normalization_index < normalization_size; normalization_index++) {
            size_t row_offset = block_offset + (normalization_index * block_size);
            for(size_t position = 0; position < block_size; position++) {
                float deviation = input.data[row_offset + position] - means[position];
                inverse_standard_deviations[position] += deviation * deviation;
            }
        }
        for(size_t position = 0; position < block_size; position++) {
            inverse_standard_deviations[position] = 1.0f / power_float((inverse_standard_deviations[position] / normalization_count) + epsilon, SQUARE_ROOT_EXPONENT);
        }

        for(size_t normalization_index = 0; normalization_index < normalization_size; normalization_index++) {
            size_t row_offset = block_offset + (normalization_index * block_size);
            for(size_t position = 0; position < block_size; position++) {
                float normalized = (input.data[row_offset + position] - means[position]) * inverse_standard_deviations[position];
                float upstream_gradient = upstream_gradients.data[row_offset + position];
                float normalized_gradient = upstream_gradient * gamma.data[normalization_index];
                gamma_gradients->data[normalization_index] += upstream_gradient * normalized;
                beta_gradients->data[normalization_index] += upstream_gradient;
                gradient_means[position] += normalized_gradient;
                gradient_projection_means[position] += normalized_gradient * normalized;
            }
        }
        for(size_t position = 0; position < block_size; position++) {
            gradient_means[position] /= normalization_count;
            gradient_projection_means[position] /= normalization_count;
        }

        for(size_t normalization_index = 0; normalization_index < normalization_size; normalization_index++) {
            size_t row_offset = block_offset + (normalization_index * block_size);
            for(size_t position = 0; position < block_size; position++) {
                float normalized = (input.data[row_offset + position] - means[position]) * inverse_standard_deviations[position];
                float normalized_gradient = upstream_gradients.data[row_offset + position] * gamma.data[normalization_index];
                input_gradients->data[row_offset + position] += ((normalized_gradient - gradient_means[position]) - (normalized * gradient_projection_means[position])) * inverse_standard_deviations[position];
            }
        }
    }

    free(means);
    free(inverse_standard_deviations);
    free(gradient_means);
    free(gradient_projection_means);
}

void tensor_rms_normalization_gradients(const Tensor input, const Tensor gamma, const Tensor upstream_gradients, Tensor* input_gradients, Tensor* gamma_gradients, const size_t normalization_dimension, const float epsilon) {
    const float SQUARE_ROOT_EXPONENT = 0.5f;

    size_t total_blocks = 1;
    size_t block_size = 1;
    for(size_t i = 0; i < input.total_dimensions; i++) {
        if(i < normalization_dimension) {
            total_blocks *= input.dimensions[i];
        }
        if(i > normalization_dimension) {
            block_size *= input.dimensions[i];
        }
    }
    size_t normalization_size = input.dimensions[normalization_dimension];
    size_t outer_block_size = normalization_size * block_size;
    float normalization_count = (float)normalization_size;

    float* inverse_root_mean_squares = malloc(block_size * sizeof(float));
    float* gradient_projection_means = malloc(block_size * sizeof(float));

    for(size_t block_index = 0; block_index < total_blocks; block_index++) {
        size_t block_offset = block_index * outer_block_size;
        for(size_t position = 0; position < block_size; position++) {
            inverse_root_mean_squares[position] = 0.0f;
            gradient_projection_means[position] = 0.0f;
        }

        for(size_t normalization_index = 0; normalization_index < normalization_size; normalization_index++) {
            size_t row_offset = block_offset + (normalization_index * block_size);
            for(size_t position = 0; position < block_size; position++) {
                float value = input.data[row_offset + position];
                inverse_root_mean_squares[position] += value * value;
            }
        }
        for(size_t position = 0; position < block_size; position++) {
            inverse_root_mean_squares[position] = 1.0f / power_float((inverse_root_mean_squares[position] / normalization_count) + epsilon, SQUARE_ROOT_EXPONENT);
        }

        for(size_t normalization_index = 0; normalization_index < normalization_size; normalization_index++) {
            size_t row_offset = block_offset + (normalization_index * block_size);
            for(size_t position = 0; position < block_size; position++) {
                float normalized = input.data[row_offset + position] * inverse_root_mean_squares[position];
                float upstream_gradient = upstream_gradients.data[row_offset + position];
                float normalized_gradient = upstream_gradient * gamma.data[normalization_index];
                gamma_gradients->data[normalization_index] += upstream_gradient * normalized;
                gradient_projection_means[position] += normalized_gradient * normalized;
            }
        }
        for(size_t position = 0; position < block_size; position++) {
            gradient_projection_means[position] /= normalization_count;
        }

        for(size_t normalization_index = 0; normalization_index < normalization_size; normalization_index++) {
            size_t row_offset = block_offset + (normalization_index * block_size);
            for(size_t position = 0; position < block_size; position++) {
                float normalized = input.data[row_offset + position] * inverse_root_mean_squares[position];
                float normalized_gradient = upstream_gradients.data[row_offset + position] * gamma.data[normalization_index];
                input_gradients->data[row_offset + position] += (normalized_gradient - (normalized * gradient_projection_means[position])) * inverse_root_mean_squares[position];
            }
        }
    }

    free(inverse_root_mean_squares);
    free(gradient_projection_means);
}

void softmax_gradients(const Tensor input, const Tensor upstream_gradients, Tensor* input_gradients, const size_t batch_dimension) {
    size_t total_blocks = 1;
    size_t block_size = 1;
    for(size_t i = 0; i < input.total_dimensions; i++) {
        if(i < batch_dimension) {
            total_blocks *= input.dimensions[i];
        }
        if(i > batch_dimension) {
            block_size *= input.dimensions[i];
        }
    }
    size_t softmax_size = input.dimensions[batch_dimension];
    size_t outer_block_size = softmax_size * block_size;

    float* probabilities = malloc(outer_block_size * sizeof(float));
    float* maximums = malloc(block_size * sizeof(float));
    float* inverse_sums = malloc(block_size * sizeof(float));
    float* gradient_dot_products = malloc(block_size * sizeof(float));

    for(size_t block_index = 0; block_index < total_blocks; block_index++) {
        size_t block_offset = block_index * outer_block_size;
        for(size_t position = 0; position < block_size; position++) {
            maximums[position] = input.data[block_offset + position];
            inverse_sums[position] = 0.0f;
            gradient_dot_products[position] = 0.0f;
        }

        for(size_t softmax_index = 1; softmax_index < softmax_size; softmax_index++) {
            size_t row_offset = block_offset + (softmax_index * block_size);
            for(size_t position = 0; position < block_size; position++) {
                if(input.data[row_offset + position] > maximums[position]) {
                    maximums[position] = input.data[row_offset + position];
                }
            }
        }

        for(size_t softmax_index = 0; softmax_index < softmax_size; softmax_index++) {
            size_t row_offset = block_offset + (softmax_index * block_size);
            size_t probability_offset = softmax_index * block_size;
            for(size_t position = 0; position < block_size; position++) {
                probabilities[probability_offset + position] = exponential_float(input.data[row_offset + position] - maximums[position]);
                inverse_sums[position] += probabilities[probability_offset + position];
            }
        }
        for(size_t position = 0; position < block_size; position++) {
            inverse_sums[position] = 1.0f / inverse_sums[position];
        }

        for(size_t softmax_index = 0; softmax_index < softmax_size; softmax_index++) {
            size_t row_offset = block_offset + (softmax_index * block_size);
            size_t probability_offset = softmax_index * block_size;
            for(size_t position = 0; position < block_size; position++) {
                probabilities[probability_offset + position] *= inverse_sums[position];
                gradient_dot_products[position] += upstream_gradients.data[row_offset + position] * probabilities[probability_offset + position];
            }
        }

        for(size_t softmax_index = 0; softmax_index < softmax_size; softmax_index++) {
            size_t row_offset = block_offset + (softmax_index * block_size);
            size_t probability_offset = softmax_index * block_size;
            for(size_t position = 0; position < block_size; position++) {
                input_gradients->data[row_offset + position] += probabilities[probability_offset + position] * (upstream_gradients.data[row_offset + position] - gradient_dot_products[position]);
            }
        }
    }

    free(probabilities);
    free(maximums);
    free(inverse_sums);
    free(gradient_dot_products);
}

void sigmoid_gradients(const Tensor input, const Tensor upstream_gradients, Tensor* input_gradients) {
    size_t total_elements = 1;
    for(size_t i = 0; i < input.total_dimensions; i++) {
        total_elements *= input.dimensions[i];
    }

    for(size_t i = 0; i < total_elements; i++) {
        float decay = exponential_float(-1.0f * absolute_value_float(input.data[i]));
        float denominator = 1.0f + decay;
        float derivative = decay / (denominator * denominator);
        input_gradients->data[i] += upstream_gradients.data[i] * derivative;
    }
}

void gelu_gradients(const Tensor input, const Tensor upstream_gradients, Tensor* input_gradients) {
    const float SQUARE_ROOT_OF_TWO_OVER_PI = 0.7978845608f;
    const float CUBIC_COEFFICIENT = 0.044715f;

    size_t total_elements = 1;
    for(size_t i = 0; i < input.total_dimensions; i++) {
        total_elements *= input.dimensions[i];
    }

    for(size_t i = 0; i < total_elements; i++) {
        float value = input.data[i];
        float value_squared = value * value;
        float argument = SQUARE_ROOT_OF_TWO_OVER_PI * (value + (CUBIC_COEFFICIENT * (value_squared * value)));
        float argument_slope = SQUARE_ROOT_OF_TWO_OVER_PI * (1.0f + ((3.0f * CUBIC_COEFFICIENT) * value_squared));

        float decay = exponential_float(-2.0f * absolute_value_float(argument));
        float denominator = 1.0f + decay;
        float logistic = 1.0f / denominator;
        float logistic_complement = decay / denominator;
        if(argument < 0.0f) {
            logistic = decay / denominator;
            logistic_complement = 1.0f / denominator;
        }

        float derivative = logistic;
        float logistic_slope = logistic * logistic_complement;
        if(logistic_slope > 0.0f) {
            derivative += ((2.0f * value) * argument_slope) * logistic_slope;
        }
        input_gradients->data[i] += upstream_gradients.data[i] * derivative;
    }
}

