void gelu_sinc_gradients(const Tensor input, const Tensor upstream_gradients, Tensor* input_gradients) {
    const uint8_t SERIES_TERMS = 6;
    const float SQUARE_ROOT_OF_TWO_OVER_PI = 0.7978845608f;
    const float CUBIC_COEFFICIENT = 0.044715f;
    const float PI = 3.14159265f;
    const float SINC_SCALE = 0.5f;
    const float SERIES_LIMIT = 1.0f;

    size_t total_elements = 1;
    for(size_t i = 0; i < input.total_dimensions; i++) {
        total_elements *= input.dimensions[i];
    }

    for(size_t i = 0; i < total_elements; i++) {
        float value = input.data[i];
        float value_squared = value * value;
        float argument = SQUARE_ROOT_OF_TWO_OVER_PI * (value + (CUBIC_COEFFICIENT * (value_squared * value)));
        float argument_slope = SQUARE_ROOT_OF_TWO_OVER_PI * (1.0f + ((3.0f * CUBIC_COEFFICIENT) * value_squared));

        float decay = exponential_float(-2.0f * absolute_value_float(argument));
        float denominator = 1.0f + decay;
        float logistic = 1.0f / denominator;
        float logistic_complement = decay / denominator;
        if(argument < 0.0f) {
            logistic = decay / denominator;
            logistic_complement = 1.0f / denominator;
        }

        float gelu = value * logistic;
        float gelu_derivative = logistic;
        float logistic_slope = logistic * logistic_complement;
        if(logistic_slope > 0.0f) {
            gelu_derivative += ((2.0f * value) * argument_slope) * logistic_slope;
        }

        float scaled = PI * value;
        float sinc = 1.0f;
        if(value != 0.0f) {
            sinc = sine_float(scaled) / scaled;
        }
        float sinc_slope = 0.0f;
        if(absolute_value_float(scaled) < SERIES_LIMIT) {
            float scaled_squared = scaled * scaled;
            float series = 1.0f;
            for(uint8_t term_number = SERIES_TERMS; term_number > 0; term_number--) {
                float even_number = 2.0f * ((float)term_number);
                series = 1.0f - ((series * scaled_squared) / (even_number * (even_number + 3.0f)));
            }
            sinc_slope = ((-1.0f * scaled) / 3.0f) * series;
        }
        else {
            sinc_slope = (cosine_float(scaled) - sinc) / scaled;
        }

        float derivative = (gelu_derivative * (1.0f + (SINC_SCALE * sinc))) + ((gelu * SINC_SCALE) * (PI * sinc_slope));
        input_gradients->data[i] += upstream_gradients.data[i] * derivative;
    }
}

