uint64_t geology_mix(uint64_t value) {
    uint64_t x = value + UINT64_C(0x9E3779B97F4A7C15);
    x = (x ^ (x >> 30)) * UINT64_C(0xBF58476D1CE4E5B9);
    x = (x ^ (x >> 27)) * UINT64_C(0x94D049BB133111EB);
    return x ^ (x >> 31);
}

uint64_t geology_hash(uint64_t seed, uint64_t kind, uint64_t a, uint64_t b, uint64_t c) {
    uint64_t hash = geology_mix(seed);
    hash = geology_mix(hash ^ kind);
    hash = geology_mix(hash ^ a);
    hash = geology_mix(hash ^ b);
    hash = geology_mix(hash ^ c);
    return hash;
}

double geology_uniform(uint64_t hash) {
    return (((double)(hash >> 11)) + 0.5) * (1.0 / 9007199254740992.0);
}

double geology_log10(double value) {
    return natural_logarithm_double(value) / GEOLOGY_NATURAL_LOGARITHM_OF_TEN;
}

double geology_power_of_ten(double value) {
    return exponential_double(value * GEOLOGY_NATURAL_LOGARITHM_OF_TEN);
}

void geology_settings_create(GeologySettings *settings) {
    const double BOUNDARY_WEIGHTS[TOTAL_BOUNDARY_TYPES] = {0.0, 0.25, 1.0, 0.7, 0.8};
    const double MAXIMUM_MAGNITUDES[TOTAL_BOUNDARY_TYPES] = {7.0, 6.5, 9.5, 8.5, 8.0};
    const double ERUPTION_RATES[TOTAL_ERUPTION_SOURCES] = {7.1e-15, 7.1e-16, 2.5e-15};
    const double MAXIMUM_VEI[TOTAL_ERUPTION_SOURCES] = {8.0, 2.0, 8.0};
    settings->seed = 0;
    settings->epoch_days = 1.0;
    settings->rate_multiplier = 1.0;
    settings->total_hotspots = 12;
    settings->hotspot_radius_radians = 0.05;
    settings->boundary_sharpness = 4.0;
    settings->earthquake_minimum_magnitude = 4.0;
    settings->gutenberg_richter_b = 1.0;
    settings->earthquake_background_per_square_metre_per_day = 3.7e-15;
    settings->earthquake_boundary_per_square_metre_per_day = 3.0e-13;
    for(size_t i = 0; i < TOTAL_BOUNDARY_TYPES; i++) {
        settings->earthquake_boundary_weights[i] = BOUNDARY_WEIGHTS[i];
        settings->maximum_magnitudes[i] = MAXIMUM_MAGNITUDES[i];
    }
    for(size_t i = 0; i < TOTAL_ERUPTION_SOURCES; i++) {
        settings->eruptions_per_square_metre_per_day[i] = ERUPTION_RATES[i];
        settings->maximum_vei[i] = MAXIMUM_VEI[i];
    }
    settings->vei_decades_per_step = 0.6;
}

void geology_configure(Geology *geology, const GeologySettings *settings, uint64_t planet_seed) {
    const double FULL_TURN = 6.28318530717958647692;
    geology->settings = *settings;
    if(geology->settings.seed == 0) {
        geology->settings.seed = geology_hash(planet_seed, GEOLOGY_KIND_SEED, 0, 0, 0) | UINT64_C(1);
    }
    if(geology->settings.epoch_days <= 0.0) {
        geology->settings.epoch_days = 1.0;
    }
    geology->total_hotspots = geology->settings.total_hotspots;
    if(geology->total_hotspots > GEOLOGY_MAXIMUM_HOTSPOTS) {
        geology->total_hotspots = GEOLOGY_MAXIMUM_HOTSPOTS;
    }
    for(size_t h = 0; h < GEOLOGY_MAXIMUM_HOTSPOTS; h++) {
        for(size_t axis = 0; axis < TOTAL_SPATIAL_AXES; axis++) {
            geology->hotspots[h][axis] = 0.0;
        }
    }
    for(size_t h = 0; h < geology->total_hotspots; h++) {
        double z = (2.0 * geology_uniform(geology_hash(geology->settings.seed, GEOLOGY_KIND_HOTSPOT, h, 0, 0))) - 1.0;
        double phi = FULL_TURN * geology_uniform(geology_hash(geology->settings.seed, GEOLOGY_KIND_HOTSPOT, h, 1, 0));
        double r = 1.0 - (z * z);
        r = (r > 0.0) ? power_double(r, 0.5) : 0.0;
        geology->hotspots[h][0] = r * cosine_double(phi);
        geology->hotspots[h][1] = r * sine_double(phi);
        geology->hotspots[h][2] = z;
    }
}

