void cohort_copy_quotas_and_diagnostics(Cohort *destination, const Cohort *source) {
    destination->minimum_nitrogen_quota = source->minimum_nitrogen_quota;
    destination->maximum_nitrogen_quota = source->maximum_nitrogen_quota;
    destination->minimum_phosphorus_quota = source->minimum_phosphorus_quota;
    destination->maximum_phosphorus_quota = source->maximum_phosphorus_quota;
    destination->carbon_electrons_per_mol_carbon = source->carbon_electrons_per_mol_carbon;
    destination->mutational_load_factor = source->mutational_load_factor;
    microbial_genome_copy(&destination->genome, &source->genome);
    destination->absorbed_photons_mol_per_day = source->absorbed_photons_mol_per_day;
    destination->last_growth_rate_per_day = source->last_growth_rate_per_day;
}

void cohort_copy(Cohort *destination, const Cohort *source) {
    cohort_copy_location_and_ledger(destination, source);
    cohort_copy_physiology(destination, source);
    cohort_copy_quotas_and_diagnostics(destination, source);
    for(size_t i = 0; i < TOTAL_MAXIMUM_COHORT_LEGS; i++) {
        destination->allocations[i] = source->allocations[i];
        destination->allocation_centres[i] = source->allocation_centres[i];
        destination->last_leg_returns_joules_per_day[i] = source->last_leg_returns_joules_per_day[i];
        destination->last_leg_fluxes_mol_electrons_per_day[i] = source->last_leg_fluxes_mol_electrons_per_day[i];
    }
    destination->leg_rate_scale_mol_electrons_per_mol_carbon_per_day = source->leg_rate_scale_mol_electrons_per_mol_carbon_per_day;
    destination->regulation_width = source->regulation_width;
    destination->regulation_time_days = source->regulation_time_days;
    destination->attached_fraction = source->attached_fraction;
    destination->last_energy_deficit_joules_per_day = source->last_energy_deficit_joules_per_day;
    destination->last_potential_growth_rate_per_day = source->last_potential_growth_rate_per_day;
}

