void planet_vertex_reset_terrain(Planet_Vertex *vertex) {
    vertex->terrain_layers_length = 0;
    for(size_t layer = 0; layer < TOTAL_TERRAIN_LAYERS; layer++) {
        vertex->terrain_layer_thickness_metres[layer] = 0.0;
        vertex->terrain_layer_temperature_kelvin[layer] = DEFAULT_WORLD_TEMPERATURE_KELVIN;
        vertex->terrain_layer_water_saturation_fraction[layer] = 1.0;
        vertex->terrain_layer_porewater_ph[layer] = NEUTRAL_PH;
        for(size_t i = 0; i < TOTAL_SOIL_TYPES; i++) {
            vertex->terrain_layer_soil_mass_kilograms[layer][i] = 0.0;
        }
        for(size_t i = 0; i < TOTAL_MINERAL_TYPES; i++) {
            vertex->terrain_layer_mineral_amounts_mol[layer][i] = 0.0;
            vertex->terrain_layer_mineral_compensation_mol[layer][i] = 0.0;
        }
        for(size_t i = 0; i < TOTAL_DISSOLVED_SPECIES; i++) {
            vertex->terrain_layer_porewater_dissolved_amounts_mol[layer][i] = 0.0;
            vertex->terrain_layer_porewater_dissolved_compensation_mol[layer][i] = 0.0;
        }
        for(size_t class_index = 0; class_index < TOTAL_ORGANIC_PARTICULATE_CLASSES; class_index++) {
            vertex->terrain_layer_organic_particulate_amounts_mol_carbon[layer][class_index] = 0.0;
            vertex->terrain_layer_organic_particulate_compensation_mol_carbon[layer][class_index] = 0.0;
            for(size_t i = 0; i < TOTAL_CONSERVED_COMPONENTS; i++) {
                vertex->terrain_layer_organic_particulate_compositions[layer][class_index][i] = PLANET_ORGANIC_PARTICULATE_DEFAULT_COMPOSITIONS[class_index][i];
            }
        }
    }
    for(size_t i = 0; i < TOTAL_MINERAL_TYPES; i++) {
        vertex->lithosphere_mineral_amounts_mol[i] = 0.0;
        vertex->lithosphere_mineral_compensation_mol[i] = 0.0;
    }
}

void planet_vertex_reset_water(Planet_Vertex *vertex) {
    vertex->water_layers_length = 0;
    for(size_t layer = 0; layer < TOTAL_WATER_LAYERS; layer++) {
        vertex->water_layer_thickness_metres[layer] = 0.0;
        vertex->water_layer_temperature_kelvin[layer] = DEFAULT_WORLD_TEMPERATURE_KELVIN;
        vertex->water_layer_ph[layer] = NEUTRAL_PH;
        vertex->water_layer_free_carbon_dioxide_mol_per_litre[layer] = 0.0;
        vertex->water_layer_light_at_top_watts_per_square_metre[layer] = 0.0;
        for(size_t i = 0; i < TOTAL_DISSOLVED_SPECIES; i++) {
            vertex->water_layer_dissolved_amounts_mol[layer][i] = 0.0;
            vertex->water_layer_dissolved_compensation_mol[layer][i] = 0.0;
        }
        for(size_t i = 0; i < TOTAL_MINERAL_TYPES; i++) {
            vertex->water_layer_suspended_mineral_amounts_mol[layer][i] = 0.0;
            vertex->water_layer_suspended_mineral_compensation_mol[layer][i] = 0.0;
        }
        for(size_t class_index = 0; class_index < TOTAL_ORGANIC_PARTICULATE_CLASSES; class_index++) {
            vertex->water_layer_organic_particulate_amounts_mol_carbon[layer][class_index] = 0.0;
            vertex->water_layer_organic_particulate_compensation_mol_carbon[layer][class_index] = 0.0;
            for(size_t i = 0; i < TOTAL_CONSERVED_COMPONENTS; i++) {
                vertex->water_layer_organic_particulate_compositions[layer][class_index][i] = PLANET_ORGANIC_PARTICULATE_DEFAULT_COMPOSITIONS[class_index][i];
            }
        }
    }
}

void planet_vertex_create(Planet_Vertex *vertex) {
    vertex->latitude_radians = 0.0;
    vertex->area_square_metres = 1.0;
    planet_vertex_reset_terrain(vertex);
    vertex->snow_water_equivalent_metres = 0.0;
    planet_vertex_reset_water(vertex);
    vertex->phototroph_cover_fraction = 0.0;
    vertex->phototroph_cover_albedo = 0.0;
    vertex->local_air_temperature_kelvin = DEFAULT_WORLD_TEMPERATURE_KELVIN;
    vertex->insolation_fraction = 1.0;
    vertex->elevation_metres = 0.0;
    vertex->surface_light_watts_per_square_metre = 0.0;
    vertex->water_body_index = SIZE_MAX;
    vertex->is_ocean_water = 0;
    vertex->plant_cover_fraction = 0.0;
    vertex->plant_cover_albedo = 0.0;
    vertex->last_transpiration_kilograms = 0.0;
}

void planet_fill_species_tables(Planet *planet) {
    for(size_t species = 0; species < TOTAL_DISSOLVED_SPECIES; species++) {
        for(size_t i = 0; i < TOTAL_CONSERVED_COMPONENTS; i++) {
            planet->dissolved_species_compositions[species][i] = PLANET_DISSOLVED_SPECIES_COMPOSITIONS[species][i];
        }
        planet->dissolved_species_conservative_charges[species] = PLANET_DISSOLVED_SPECIES_CONSERVATIVE_CHARGES[species];
        planet->dissolved_species_alkalinity_contributions[species] = PLANET_DISSOLVED_SPECIES_CONSERVATIVE_CHARGES[species];
    }
    for(size_t gas = 0; gas < TOTAL_GAS_SPECIES; gas++) {
        for(size_t i = 0; i < TOTAL_CONSERVED_COMPONENTS; i++) {
            planet->gas_species_compositions[gas][i] = PLANET_GAS_SPECIES_COMPOSITIONS[gas][i];
        }
        planet->gas_henry_constants_mol_per_litre_atmosphere[gas] = PLANET_HENRY_CONSTANTS_MOL_PER_LITRE_ATMOSPHERE[gas];
        planet->gas_henry_temperature_factors_kelvin[gas] = PLANET_HENRY_TEMPERATURE_FACTORS_KELVIN[gas];
        planet->gas_dissolved_counterparts[gas] = PLANET_GAS_DISSOLVED_COUNTERPARTS[gas];
    }
    for(size_t mineral = 0; mineral < TOTAL_MINERAL_TYPES; mineral++) {
        for(size_t i = 0; i < TOTAL_CONSERVED_COMPONENTS; i++) {
            planet->mineral_compositions[mineral][i] = PLANET_MINERAL_COMPOSITIONS[mineral][i];
        }
    }
    for(size_t class_index = 0; class_index < TOTAL_ORGANIC_PARTICULATE_CLASSES; class_index++) {
        for(size_t i = 0; i < TOTAL_CONSERVED_COMPONENTS; i++) {
            planet->organic_particulate_default_compositions[class_index][i] = PLANET_ORGANIC_PARTICULATE_DEFAULT_COMPOSITIONS[class_index][i];
        }
    }
}

void planet_reset_ledger(Planet *planet) {
    const double TRANSFER_RELATIVE_TOLERANCE = 1e-12;
    planet->transfer_relative_tolerance = TRANSFER_RELATIVE_TOLERANCE;
}

void planet_create(Planet *planet, uint64_t seed) {
    const uint64_t SPREAD = UINT64_C(11400714819323198485);
    const double PLANET_TEMPERATURE_KELVIN = 288.15;
    planet->seed = seed;
    planet->pcg_state_for_soil_types = seed + SPREAD;
    planet->pcg_inc_for_soil_types = 1;
    planet->pcg_state_for_hydrosphere = seed + (2 * SPREAD);
    planet->pcg_inc_for_hydrosphere = 11;
    planet->radius_metres = 6.371e6;
    planet->gravity_metres_per_second_squared = 9.81;
    planet->solar_constant_watts_per_square_metre = 917.0;
    planet->relative_luminosity = 1.0;
    planet->areal_heat_capacity_joules_per_square_metre_kelvin = 0.0;
    planet->effective_emissivity = 1.0;
    planet->local_heat_redistribution_kelvin_per_albedo = 20.0;
    planet->geological_acceleration_factor = 1.0;
    for(size_t i = 0; i < TOTAL_GAS_SPECIES; i++) {
        planet->atmosphere_gas_amounts_mol[i] = 0.0;
        planet->atmosphere_gas_compensation_mol[i] = 0.0;
    }
    planet->atmosphere_mean_temperature_kelvin = DEFAULT_WORLD_TEMPERATURE_KELVIN;
    planet_fill_species_tables(planet);
    planet->subdivision_levels = 0;
    planet->vertices_length = 0;
    planet->vertices = NULL;
    planet->neighbor_indices = NULL;
    planet->total_neighbors = NULL;
    planet_reset_ledger(planet);
    planet->current_time_days = 0.0;
    planet->is_temperature_imposed = 0;
    planet->imposed_temperature_kelvin = DEFAULT_WORLD_TEMPERATURE_KELVIN;
    planet->atmosphere_mean_temperature_kelvin = PLANET_TEMPERATURE_KELVIN;
    planet->cohorts_length = 0;
    planet->cohorts_capacity = 0;
    planet->cohorts = NULL;
    planet->animals_length = 0;
    planet->animals_capacity = 0;
    planet->animals = NULL;
    planet->pathogens_length = 0;
    planet->pathogens_capacity = 0;
    planet->pathogens = NULL;
    planet->plants_length = 0;
    planet->plants_capacity = 0;
    planet->plants = NULL;
    planet->next_lineage = 0;
    planet->tectonics.total_plates = 0;
    planet->ocean_body_index = SIZE_MAX;
    planet->terrain_version = 1;
    planet->ocean_surface_layer_metres = 50.0;
    planet->lake_surface_layer_metres = 10.0;
    planet->maximum_water_layers = 2;
    planet->tectonics.belt_width_radians = 0.0;
    for(size_t i = 0; i < TERRAIN_PERMUTATION_LENGTH; i++) {
        planet->tectonics.permutation[i] = 0;
    }
    for(size_t p = 0; p < TERRAIN_MAXIMUM_PLATES; p++) {
        for(size_t axis = 0; axis < TOTAL_SPATIAL_AXES; axis++) {
            planet->tectonics.centres[p][axis] = 0.0;
            planet->tectonics.spins[p][axis] = 0.0;
        }
        planet->tectonics.offsets[p] = 0.0;
    }
    GeologySettings geology_defaults;
    geology_settings_create(&geology_defaults);
    geology_configure(&planet->geology, &geology_defaults, seed);
    planet->vertex_positions = NULL;
    planet->geology_sites = NULL;
    planet->climate = NULL;
}

void planet_destroy(Planet *planet) {
    free(planet->vertices);
    free(planet->neighbor_indices);
    free(planet->total_neighbors);
    free(planet->vertex_positions);
    free(planet->geology_sites);
    climate_destroy(planet->climate);
    free(planet->cohorts);
    free(planet->animals);
    free(planet->pathogens);
    free(planet->plants);
    planet_create(planet, planet->seed);
}

double planet_water_layer_volume_litres(const Planet_Vertex *vertex, size_t layer_index) {
    return (vertex->water_layer_thickness_metres[layer_index] * vertex->area_square_metres) * LITRES_PER_CUBIC_METRE;
}

double planet_terrain_porosity(const Planet_Vertex *vertex, size_t layer_index) {
    double mass = 0.0;
    double weighted = 0.0;
    double porosity = DEFAULT_SEDIMENT_POROSITY;
    for(size_t i = 0; i < TOTAL_SOIL_TYPES; i++) {
        mass = mass + vertex->terrain_layer_soil_mass_kilograms[layer_index][i];
        weighted = weighted + (vertex->terrain_layer_soil_mass_kilograms[layer_index][i] * SOIL_TYPE_POROSITIES[i]);
    }
    if(mass > 0.0) {
        porosity = weighted / mass;
    }
    return porosity;
}

double planet_terrain_porewater_litres(const Planet_Vertex *vertex, size_t layer_index) {
    const double BULK = vertex->terrain_layer_thickness_metres[layer_index] * vertex->area_square_metres;
    const double FILLED = planet_terrain_porosity(vertex, layer_index) * vertex->terrain_layer_water_saturation_fraction[layer_index];
    return (BULK * FILLED) * LITRES_PER_CUBIC_METRE;
}

double planet_gas_temperature_kelvin(const Planet *planet) {
    double temperature = planet->atmosphere_mean_temperature_kelvin;
    if(planet->is_temperature_imposed == 1) {
        temperature = planet->imposed_temperature_kelvin;
    }
    return temperature;
}

double planet_gas_amount_for_partial_pressure(const Planet *planet, size_t gas_index, double pascals) {
    double amount = 0.0;
    if(gas_index < TOTAL_GAS_SPECIES) {
        double area = 0.0;
        for(size_t vertex_index = 0; vertex_index < planet->vertices_length; vertex_index++) {
            area = area + planet->vertices[vertex_index].area_square_metres;
        }
        amount = (pascals * area) / (planet->gravity_metres_per_second_squared * AIR_MOLAR_MASS_KILOGRAMS_PER_MOL);
    }
    return amount;
}

#define STREAM_DEMOGRAPHY 1
#define STREAM_FUNNEL 3
#define STREAM_TOPOLOGY 9
#define STREAM_PLANET_PARAMETERS 13
#define POISSON_MAXIMUM_ATTEMPTS 1000

PCG stream_create(uint64_t seed, uint64_t world_index, uint64_t purpose) {
    const uint64_t STREAM = (world_index * UINT64_C(65536)) + purpose;
    return create_PCG(seed, (2 * STREAM) + 1);
}

double square_root_double(double value) {
    double root = 0.0;
    if(value > 0.0) {
        root = power_double(value, 0.5);
    }
    return root;
}

double stream_uniform(PCG *generator) {
    double draw = uniform_double_generator(generator, 0.0, 1.0);
    if(draw >= 1.0) {
        draw = 0.0;
    }
    return draw;
}

double stream_uniform_open(PCG *generator) {
    const double SMALLEST = 1.1102230246251565e-16;
    return uniform_double_generator(generator, SMALLEST, 1.0 - SMALLEST);
}

double stream_normal(PCG *generator) {
    return gaussian_double_generator(generator, 0.0, 1.0);
}

double log_factorial(uint64_t k) {
    const uint64_t EXACT_LIMIT = 30;
    const double HALF_LOG_TWO_PI = 0.91893853320467274178;
    double value = 0.0;
    if(k < EXACT_LIMIT) {
        for(uint64_t i = 2; i <= k; i++) {
            value = value + natural_logarithm_double((double)i);
        }
    } else {
        double x = (double)k;
        double inverse = 1.0 / x;
        value = (x * natural_logarithm_double(x)) - x + (0.5 * natural_logarithm_double(x)) + HALF_LOG_TWO_PI;
        value = value + (inverse / 12.0) - ((inverse * inverse * inverse) / 360.0);
    }
    return value;
}

uint64_t stream_poisson_small(PCG *generator, double mean) {
    const double LIMIT = exponential_double(-mean);
    const uint64_t MAXIMUM_COUNT = 200;
    double product = stream_uniform(generator);
    uint64_t count = 0;
    for(uint64_t i = 0; i < MAXIMUM_COUNT; i++) {
        if(product < LIMIT) {
            break;
        }
        count = count + 1;
        product = product * stream_uniform(generator);
    }
    return count;
}

double stream_gamma(PCG *generator, double shape) {
    double boost = 1.0;
    double value = 0.0;
    if(shape <= 0.0) {
        return 0.0;
    }
    if(shape < 1.0) {
        boost = exponential_double(natural_logarithm_double(stream_uniform_open(generator)) / shape);
        shape = shape + 1.0;
    }
    const double D = shape - (1.0 / 3.0);
    const double C = 1.0 / square_root_double(9.0 * D);
    for(size_t attempt = 0; attempt < 1000; attempt++) {
        double x = stream_normal(generator);
        double v = 1.0 + (C * x);
        if(v > 0.0) {
            v = v * v * v;
            double u = stream_uniform_open(generator);
            if((u < (1.0 - (0.0331 * x * x * x * x))) || (natural_logarithm_double(u) < ((0.5 * x * x) + (D * (1.0 - v + natural_logarithm_double(v)))))) {
                value = D * v;
                break;
            }
        }
        value = D;
    }
    return value * boost;
}

uint64_t stream_poisson(PCG *generator, double mean) {
    const double SMALL_MEAN_LIMIT = 10.0;
    uint64_t draw = 0;
    if((mean > 0.0) && (mean < SMALL_MEAN_LIMIT)) {
        draw = stream_poisson_small(generator, mean);
    } else if(mean >= SMALL_MEAN_LIMIT) {
        const double ROOT = square_root_double(mean);
        const double B = 0.931 + (2.53 * ROOT);
        const double A = -0.059 + (0.02483 * B);
        const double INVERSE_ALPHA = 1.1239 + (1.1328 / (B - 3.4));
        const double V_R = 0.9277 - (3.6224 / (B - 2.0));
        const double LOG_MEAN = natural_logarithm_double(mean);
        uint8_t is_accepted = 0;
        draw = (uint64_t)(mean + 0.5);
        for(size_t attempt = 0; (attempt < POISSON_MAXIMUM_ATTEMPTS) && (is_accepted == 0); attempt++) {
            double u = stream_uniform(generator) - 0.5;
            double v = stream_uniform_open(generator);
            double us = 0.5 - absolute_value_double(u);
            double k = (double)(int64_t)((((2.0 * A) / us) + B) * u + mean + 0.43);
            if(((((2.0 * A) / us) + B) * u + mean + 0.43) < 0.0) {
                k = -1.0;
            }
            if((us >= 0.07) && (v <= V_R) && (k >= 0.0)) {
                draw = (uint64_t)k;
                is_accepted = 1;
            } else if((k >= 0.0) && ((us >= 0.013) || (v <= us))) {
                double left = natural_logarithm_double(v) + natural_logarithm_double(INVERSE_ALPHA) - natural_logarithm_double((A / (us * us)) + B);
                double right = -mean + (k * LOG_MEAN) - log_factorial((uint64_t)k);
                if(left <= right) {
                    draw = (uint64_t)k;
                    is_accepted = 1;
                }
            }
        }
    }
    return draw;
}

double power_of_ten(double x) {
    const double NATURAL_LOGARITHM_OF_TEN = 2.30258509299404568402;
    return exponential_double(x * NATURAL_LOGARITHM_OF_TEN);
}

#define POOL_WATER_DISSOLVED 0
#define POOL_POREWATER_DISSOLVED 1
#define POOL_TERRAIN_MINERAL 2
#define POOL_SUSPENDED_MINERAL 3
